+    static void topScores(
+        double[] start,
+        double[] end,
+        int numAnswersToGather,
+        Consumer<ScoreAndIndices> topScoresCollector,
+        int seq2Start,
+        int tokenSize,
+        int maxAnswerLength,
+        int spanIndex
