+public class ProfileHasPrivilegesResponseTests extends AbstractWireSerializingTestCase<ProfileHasPrivilegesResponse> {
+
+    @Override
+    protected Writeable.Reader<ProfileHasPrivilegesResponse> instanceReader() {
